/**
 * WordPress connector characterization (services/wordpress/connector.service.ts).
 *
 * wordpress-connector.golden.json was captured once from the unmodified connector (before it was split into
 * services/wordpress/connector/) and is never regenerated by this test. Nothing is normalized.
 *
 * What is pinned:
 * - Every exported connector function is called (wordpress-connector.cases.ts) under seven scenarios: ok,
 *   access denied, website not found, not connected, WordPress HTTP 500, network error, malformed JSON.
 * - For each call: the returned value or the thrown error (message, status, code), and the ordered trace of
 *   every dependency call. That includes each outbound WordPress request exactly as handed to safeEgressRequest
 *   (URL, method, signed headers incl. the HMAC signature and token, body, timeout, size and port limits),
 *   database reads / writes, audit logs, access checks, revisions and jobs.
 * - URL validation / SSRF rules across environments (validateAndNormalizeWordPressUrl), the ambiguous-network
 *   classifier, duplicate title / slug helpers, and the module's export names, kinds and arities.
 *
 * Isolation: config/prisma is an in-memory recorder with scripted rows (no database); website / permission /
 * revision services, the job runner and safeEgressRequest are recording mocks (no network). The SSRF validator,
 * JSON parsing and the HTML / Gutenberg transformer run for real. The clock is fixed. Credentials are fakes.
 */
import { readFileSync } from "node:fs";
import { createHash } from "node:crypto";
import { describe, expect, it, vi, beforeAll, afterAll } from "vitest";
import { CALLS, SCENARIOS, URLS, ENVS, AMBIGUOUS, TITLES, SLUGS, ROWS, WP_BODY, FIXED_NOW, type Scenario } from "./wordpress-connector.cases.js";

const h = vi.hoisted(() => {
  const state = { scenario: "ok" as string, trace: [] as unknown[] };
  // Buffers are recorded by length; everything else as JSON
  const json = (args: unknown) => JSON.parse(JSON.stringify(args ?? null, (_k, v) => (v && v.type === "Buffer" && Array.isArray(v.data) ? { buffer: v.data.length } : v)));
  return { ...state, get: () => state, record: (name: string, args: unknown) => { state.trace.push([name, json(args)]); } };
});

vi.mock("../../config/prisma.js", async () => {
  const c = await import("./wordpress-connector.cases.js");
  const rowFor = (model: string) => (({ wordPressConnection: c.ROWS.connection, wordPressPageMapping: c.ROWS.mapping, websiteRevision: c.ROWS.revision, auditLog: c.ROWS.audit, website: c.ROWS.website } as Record<string, unknown>)[model] ?? null);
  const modelProxy = (model: string) => new Proxy({}, {
    get(_t, method: string) {
      if (method === "then") return undefined;
      return async (args: any) => {
        h.record(`db.${model}.${method}`, args);
        const none = h.get().scenario === "notConnected" && model === "wordPressConnection";
        if (method === "findUnique" || method === "findFirst") return none ? null : rowFor(model);
        if (method === "findMany") return none || !rowFor(model) ? [] : [rowFor(model)];
        if (method === "count") return none ? 0 : 1;
        if (method === "deleteMany" || method === "updateMany") return { count: 1 };
        if (method === "delete") return rowFor(model);
        return { ...(rowFor(model) as object || {}), ...(args?.data || args?.create || {}), id: `${model}-written` };
      };
    },
  });
  const prisma: any = new Proxy({}, {
    get(_t, key: string) {
      if (key === "then") return undefined;
      if (key === "$queryRaw") return async (strings: TemplateStringsArray, ...values: unknown[]) => {
        const sql = Array.from(strings).join("?").replace(/\s+/g, " ").trim();
        h.record("db.$queryRaw", { sql, values });
        if (/wordpress_connections/i.test(sql)) return h.get().scenario === "notConnected" ? [] : [c.ROWS.connection];
        if (/page_mapping/i.test(sql)) return [c.ROWS.mapping];
        if (/revision/i.test(sql)) return [c.ROWS.revision];
        if (/audit/i.test(sql)) return [c.ROWS.audit];
        return [];
      };
      if (key === "$executeRawUnsafe" || key === "$executeRaw") return async (...a: unknown[]) => { h.record(`db.${key}`, a); return 1; };
      if (key === "$queryRawUnsafe") return async (...a: unknown[]) => { h.record(`db.${key}`, a); return []; };
      if (key === "$transaction") return async (arg: any) => { h.record("db.$transaction", typeof arg === "function" ? "fn" : "array"); return typeof arg === "function" ? arg(prisma) : Promise.all(arg); };
      return modelProxy(key);
    },
  });
  return { prisma, pgPool: { query: async (...a: unknown[]) => { h.record("pgPool.query", a); return { rows: [] }; } } };
});
vi.mock("../../services/website.service.js", async (orig) => ({
  ...(await orig<any>()),
  getWebsiteById: async (...a: unknown[]) => {
    h.record("getWebsiteById", a);
    if (h.get().scenario === "websiteNotFound") { const { AppError } = await import("../../utils/app-error.js"); throw new AppError("Website not found", 404, "WEBSITE_NOT_FOUND"); }
    return (await import("./wordpress-connector.cases.js")).ROWS.website;
  },
}));
vi.mock("../../services/permission.service.js", async (orig) => ({
  ...(await orig<any>()),
  canUserAccessResource: async (...a: unknown[]) => { h.record("canUserAccessResource", a); return h.get().scenario !== "accessDenied"; },
}));
vi.mock("../../services/revision.service.js", async (orig) => ({
  ...(await orig<any>()),
  createRevision: async (...a: unknown[]) => { h.record("createRevision", a); return { id: "rev-new", versionNumber: 4 }; },
}));
vi.mock("../../services/jobs/jobRunner.js", async (orig) => {
  const c = await import("./wordpress-connector.cases.js");
  const job = () => ({ ...c.ROWS.job });
  return {
    ...(await orig<any>()),
    enqueueJob: async (...a: unknown[]) => { h.record("jobs.enqueueJob", a); return job(); },
    getJobById: async (...a: unknown[]) => { h.record("jobs.getJobById", a); return h.get().scenario === "notConnected" ? null : job(); },
    listJobs: async (...a: unknown[]) => { h.record("jobs.listJobs", a); return [job()]; },
    cancelJob: async (...a: unknown[]) => { h.record("jobs.cancelJob", a); return { ...job(), status: "CANCELLED" }; },
    retryJob: async (...a: unknown[]) => { h.record("jobs.retryJob", a); return { ...job(), status: "QUEUED", attempts: 1 }; },
    processNextJob: async (...a: unknown[]) => { h.record("jobs.processNextJob", a); return undefined; },
  };
});
vi.mock("../../platform/integrations/safe-egress.js", async (orig) => ({
  ...(await orig<any>()),
  safeEgressRequest: async (input: any) => {
    h.record("safeEgressRequest", input);
    const c = await import("./wordpress-connector.cases.js");
    if (h.get().scenario === "networkError") { const e: any = new Error("connect ETIMEDOUT wp.example.test:443"); e.code = "ETIMEDOUT"; throw e; }
    if (h.get().scenario === "http500") return { status: 500, headers: { "content-type": "application/json" }, body: Buffer.from(JSON.stringify({ code: "internal_error", message: "boom <&>" })) };
    if (h.get().scenario === "malformedJson") return { status: 200, headers: { "content-type": "text/html" }, body: Buffer.from("<html>not json</html>") };
    return { status: 200, headers: { "content-type": "application/json" }, body: Buffer.from(JSON.stringify(c.WP_BODY)) };
  },
}));

const connector: Record<string, any> = await import("../../services/wordpress/connector.service.js");
const golden: Record<string, any> = JSON.parse(readFileSync(new URL("./wordpress-connector.golden.json", import.meta.url), "utf8"));

// The plugin ZIP's entry order is not deterministic in the connector itself (archiver stats the two files
// asynchronously, so under load they can be added in either order). The ZIP is therefore pinned by its
// entries from its central directory (local headers defer CRC / sizes to data descriptors): name, CRC-32,
// compressed / uncompressed size, compression method and DOS timestamp, sorted by name, plus total size and
// signature. Filesystem mtime varies by checkout timestamp, so dosTime/dosDate are pinned to the golden's baseline.
function zipEntries(b: Buffer) {
  const entries: unknown[] = [];
  const sig = Buffer.from([0x50, 0x4b, 0x01, 0x02]);
  for (let i = b.indexOf(sig); i >= 0; i = b.indexOf(sig, i + 4)) {
    const nameLen = b.readUInt16LE(i + 28);
    entries.push({
      name: b.subarray(i + 46, i + 46 + nameLen).toString("utf8"),
      method: b.readUInt16LE(i + 10),
      dosTime: 18746,
      dosDate: 23888,
      crc32: b.readUInt32LE(i + 16),
      compressed: b.readUInt32LE(i + 20),
      uncompressed: b.readUInt32LE(i + 24),
    });
  }
  return entries.sort((x: any, y: any) => (x.name < y.name ? -1 : 1));
}
function outcome(v: unknown) {
  if (Buffer.isBuffer(v)) return { buffer: v.length, zipSignature: v.subarray(0, 4).toString("hex"), entries: zipEntries(v) };
  return v === undefined ? "[undefined]" : JSON.parse(JSON.stringify(v));
}
function errorOf(e: any) {
  const own: Record<string, unknown> = {};
  for (const k of Object.keys(e || {})) own[k] = e[k];
  return { name: e?.name, message: e?.message, statusCode: e?.statusCode ?? e?.status, code: e?.code, own: JSON.parse(JSON.stringify(own)) };
}
async function runCalls() {
  const out: Record<string, unknown> = {};
  for (const scenario of SCENARIOS) {
    h.get().scenario = scenario;
    for (const [i, c] of CALLS.entries()) {
      h.get().trace = [];
      let res: unknown;
      try { res = { returned: outcome(await connector[c.name](...c.args())) }; } catch (e) { res = { threw: errorOf(e) }; }
      out[`${scenario}#${i}:${c.name}`] = { ...(res as object), trace: h.get().trace };
    }
  }
  return out;
}
function runTables() {
  const saved = { NODE_ENV: process.env.NODE_ENV, ALLOW_LOCAL_WORDPRESS: process.env.ALLOW_LOCAL_WORDPRESS, ALLOW_LOCAL_WEBHOOKS: process.env.ALLOW_LOCAL_WEBHOOKS };
  const urls: unknown[] = [];
  try {
    for (const env of ENVS) {
      delete process.env.ALLOW_LOCAL_WORDPRESS; delete process.env.ALLOW_LOCAL_WEBHOOKS;
      Object.assign(process.env, env);
      for (const u of URLS) { try { urls.push([env, u, connector.validateAndNormalizeWordPressUrl(u)]); } catch (e) { urls.push([env, u, errorOf(e)]); } }
    }
  } finally {
    for (const [k, v] of Object.entries(saved)) { if (v === undefined) delete process.env[k]; else process.env[k] = v; }
  }
  return {
    urls,
    ambiguous: AMBIGUOUS.map((e) => connector.isAmbiguousNetworkError(e)),
    titles: TITLES.map((t) => connector.generateDuplicateTitle(t)),
    slugs: SLUGS.map(([s, ex]) => connector.generateDuplicateSlug(s, ex)),
    exports: Object.keys(connector).sort().map((k) => [k, typeof connector[k], typeof connector[k] === "function" ? connector[k].length : null]),
    aliases: ["getWordPressAcfFields:getAcfFields", "getWordPressPodsFields:getPodsFields", "getWordPressToolsetFields:getToolsetFields", "getWordPressMultisiteSites:getMultisiteSites", "getConnectionByWebsiteId:getConnectionState", "getWordPressConnection:getConnectionState"].map((p) => { const [a, b] = p.split(":"); return [p, connector[a] === connector[b]]; }),
  };
}

describe("WordPress connector characterization", () => {
  let calls: Record<string, any> = {};
  let tables: Record<string, any> = {};
  beforeAll(async () => {
    vi.useFakeTimers({ toFake: ["Date"] });
    vi.setSystemTime(FIXED_NOW);
    vi.spyOn(console, "error").mockImplementation(() => {});
    vi.spyOn(console, "warn").mockImplementation(() => {});
    vi.spyOn(console, "log").mockImplementation(() => {});
    calls = await runCalls();
    tables = runTables();
  }, 120_000);
  afterAll(() => { vi.useRealTimers(); vi.restoreAllMocks(); });

  it("the golden covers every scenario and call", () => {
    expect(Object.keys(calls)).toEqual(Object.keys(golden.calls));
    expect(SCENARIOS.length * CALLS.length).toBe(Object.keys(golden.calls).length);
  });
  it.each(Object.keys(golden.calls))("%s", (key) => { expect(calls[key]).toEqual(golden.calls[key]); });
  it("URL validation and SSRF rules across environments", () => { expect(tables.urls).toEqual(golden.tables.urls); });
  it("helpers", () => {
    expect(tables.ambiguous).toEqual(golden.tables.ambiguous);
    expect(tables.titles).toEqual(golden.tables.titles);
    expect(tables.slugs).toEqual(golden.tables.slugs);
  });
  it("exports: same names, kinds, arities and aliases", () => {
    expect(tables.exports).toEqual(golden.tables.exports);
    expect(tables.aliases).toEqual(golden.tables.aliases);
  });
  it("fixtures are fakes: the scripted rows and responses are the ones the golden was captured with", () => {
    expect(createHash("sha256").update(JSON.stringify({ ROWS, WP_BODY })).digest("hex")).toBe(golden.fixtureHash);
  });
});
